<?php
session_start(); require '../config/db.php';
if (!isset($_SESSION['user_id']) || $_SESSION['role'] !== 'admin') { header('Location: ../auth/login.php'); exit(); }
if (isset($_GET['delete'])) { $id=(int)$_GET['delete']; $q=$conn->prepare('DELETE FROM categories WHERE category_id=?'); $q->bind_param('i',$id); if ($q->execute()) header('Location: manage_categories.php?message=deleted'); else header('Location: manage_categories.php?error=in_use'); exit(); }
if ($_SERVER['REQUEST_METHOD']==='POST') { $name=trim($_POST['category_name']??''); $id=filter_input(INPUT_POST,'category_id',FILTER_VALIDATE_INT); if ($name==='') $error='Enter a category name.'; else { $q=$id?$conn->prepare('UPDATE categories SET category_name=? WHERE category_id=?'):$conn->prepare('INSERT INTO categories (category_name) VALUES (?)'); if($id)$q->bind_param('si',$name,$id);else $q->bind_param('s',$name); if($q->execute()){header('Location: manage_categories.php?message='.($id?'updated':'added'));exit();}$error='That category name is already in use.'; } }
$editing=null; if(isset($_GET['edit'])){$id=(int)$_GET['edit'];$q=$conn->prepare('SELECT * FROM categories WHERE category_id=?');$q->bind_param('i',$id);$q->execute();$editing=$q->get_result()->fetch_assoc();}
$search=trim($_GET['search']??''); $sql='SELECT c.category_id,c.category_name,COUNT(s.service_id) service_count FROM categories c LEFT JOIN services s ON s.category_id=c.category_id'; if($search!=='')$sql.=' WHERE c.category_name LIKE ?';$sql.=' GROUP BY c.category_id,c.category_name ORDER BY c.category_name';$q=$conn->prepare($sql);if($search!==''){$term="%$search%";$q->bind_param('s',$term);}$q->execute();$result=$q->get_result();
?>
