<div class="row g-4"><div class="col-lg-4"><section class="admin-panel h-100"><div class="p-4"><h2 class="h5 mb-1"><?php echo $editing?'Edit Category':'Add Category';?></h2><p class="text-muted small mb-4">Keep names short and recognizable.</p><form method="post"><?php if($editing):?><input type="hidden" name="category_id" value="<?php echo (int)$editing['category_id'];?>"><?php endif;?><label class="form-label">Category name</label><input class="form-control mb-3" name="category_name" maxlength="50" required value="<?php echo htmlspecialchars($editing['category_name']??'');?>"><button class="btn btn-brand"><?php echo $editing?'Save Changes':'Add Category';?></button><?php if($editing):?> <a class="listing-action-btn" href="manage_categories.php">Cancel</a><?php endif;?></form></div></section></div><div class="col-lg-8"><section class="admin-panel table-responsive"><table class="table table-hover align-middle admin-table"><thead><tr><th>Category</th><th>Services</th><th>Actions</th></tr></thead><tbody><?php if($result->num_rows===0):?><tr><td colspan="3" class="text-center text-muted py-5">No categories found.</td></tr><?php endif;?><?php while($category=$result->fetch_assoc()):?><tr><td class="fw-semibold"><?php echo htmlspecialchars($category['category_name']);?></td><td><?php echo (int)$category['service_count'];?></td><td><a class="listing-action-btn" href="manage_categories.php?edit=<?php echo $category['category_id'];?>">Edit</a> <a class="listing-action-btn listing-action-btn-danger confirm-delete" href="manage_categories.php?delete=<?php echo $category['category_id'];?>">Delete</a></td></tr><?php endwhile;?></tbody></table></section></div></div></main></div></div><script src="../assets/js/script.js"></script></body></html>
